class NaturalRiverVariationTest{static void check(boolean b,String s){if(!b)throw new AssertionError(s);}public static void main(String[]args){int n=128;float[] ground=new float[n*n];for(int z=0;z<n;z++)for(int x=0;x<n;x++)ground[z*n+x]=(float)(90+35*Math.exp(-Math.pow((x-70)/8.,2)));double guided=RiverShape.terrainOffset(ground,n,64,64,1,0,4,1,10,1);check(guided<0,"river should avoid raised ridge to its right: "+guided);double low=10,high=-10,largestStep=0,last=0;for(int k=0;k<1000;k++){double width=RiverShape.widthFactor(k,12,.7,2024,0);low=Math.min(low,width);high=Math.max(high,width);if(k>0)largestStep=Math.max(largestStep,Math.abs(width-last));last=width;check(width==RiverShape.widthFactor(k,12,.7,2024,0),"repeatable width");}check(high-low>.25&&largestStep<.04,"smooth channel-width variation: "+low+".."+high+" step="+largestStep);double difference=0;for(int k=0;k<1000;k+=10)difference=Math.max(difference,Math.abs(RiverShape.traceBankFactor(k,-1,.8,2024)-RiverShape.traceBankFactor(k,1,.8,2024)));check(difference>.2,"independent riverbanks");check(RiverShape.widthFactor(100,12,0,2024,0)==1,"width variation can be disabled");check(RiverShape.bankFactor(100,200,1,0,0,2024)==1,"bank variation can be disabled");double a=RiverShape.bankFactor(1000,2000,1,0,.8,2024),b=RiverShape.bankFactor(1000,2000,-1,0,.8,2024);check(Math.abs(a-b)>.01,"opposite banks use different profiles");System.out.println("PASS: terrain avoidance, gradual seeded width variation "+low+".."+high+", independent banks, stable coordinates and disabled controls");}}
